import { Injectable, inject } from '@angular/core';
import { NzNotificationService, NzNotificationDataOptions } from 'ng-zorro-antd/notification';

/** Vị trí hiện thông báo (góc màn hình). */
export type HrmNotifyPlacement = 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight';

/** Tùy chọn cho 1 thông báo — không chứa text hiển thị, an toàn i18n. */
export interface HrmNotifyOptions {
  /** Góc màn hình hiện thông báo (mặc định topRight). */
  placement?: HrmNotifyPlacement;
  /** Thời gian tự đóng (ms). 0 = ở lại tới khi người dùng tự đóng. */
  duration?: number;
  /** Khóa gộp trùng — cùng key thì thông báo mới ghi đè cái cũ thay vì xếp chồng. */
  key?: string;
}

/** hrm notification — thông báo góc màn hình (title + nội dung). Bọc Nz.
 *  Tất cả method nhận thêm `options` (vị trí / thời gian / khóa gộp trùng) — không bắt buộc. */
@Injectable({ providedIn: 'root' })
export class HrmNotificationService {
  private readonly nz = inject(NzNotificationService);

  success(title: string, content: string, options?: HrmNotifyOptions): void { this.nz.success(title, content, this.map(options)); }
  info(title: string, content: string, options?: HrmNotifyOptions): void { this.nz.info(title, content, this.map(options)); }
  warning(title: string, content: string, options?: HrmNotifyOptions): void { this.nz.warning(title, content, this.map(options)); }
  error(title: string, content: string, options?: HrmNotifyOptions): void { this.nz.error(title, content, this.map(options)); }

  private map(o?: HrmNotifyOptions): NzNotificationDataOptions | undefined {
    if (!o) return undefined;
    return { nzPlacement: o.placement, nzDuration: o.duration, nzKey: o.key };
  }
}
