import { Component, inject } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { HrmButton, HrmNotificationService } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Notification (Overlay) — cấu trúc chuẩn Toast: Types / Placement / Duration / Dedup / Stacking. Song ngữ qua i18n docs.notification.*. */
@Component({
  selector: 'sg-doc-notification',
  imports: [TranslateModule, HrmButton, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Overlay" [title]="'docs.notification.title' | translate" [desc]="'docs.notification.desc' | translate">

      <div sgOverview>
        <sg-row>
          <hrm-button variant="default" (click)="ovInfo()">{{ 'docs.notification.info' | translate }}</hrm-button>
          <hrm-button variant="default" (click)="ovSuccess()">{{ 'docs.notification.success' | translate }}</hrm-button>
        </sg-row>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.notification.purpose' | translate"
          [when]="when"
          [behavior]="'docs.notification.behavior' | translate"
          [avoid]="'docs.notification.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.notification.do1' | translate }}</sg-do>
        <sg-do><span [innerHTML]="'docs.notification.do2' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.notification.do3' | translate"></span></sg-do>
        <sg-dont>{{ 'docs.notification.dont1' | translate }}</sg-dont>
        <sg-dont>{{ 'docs.notification.dont2' | translate }}</sg-dont>
        <sg-dont>{{ 'docs.notification.dont3' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.notification.exTypesT' | translate"
          [desc]="'docs.notification.exTypesD' | translate">
          <sg-row [label]="'docs.notification.rowTypes' | translate">
            <hrm-button variant="default" (click)="tInfo()">{{ 'docs.notification.info' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="tSuccess()">{{ 'docs.notification.success' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="tWarning()">{{ 'docs.notification.warning' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="tError()">{{ 'docs.notification.error' | translate }}</hrm-button>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.notification.exPlaceT' | translate"
          [desc]="'docs.notification.exPlaceD' | translate">
          <sg-row [label]="'docs.notification.rowPlace' | translate">
            <hrm-button variant="default" (click)="place('topLeft')">{{ 'docs.notification.topLeft' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="place('topRight')">{{ 'docs.notification.topRight' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="place('bottomLeft')">{{ 'docs.notification.bottomLeft' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="place('bottomRight')">{{ 'docs.notification.bottomRight' | translate }}</hrm-button>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.notification.exDurationT' | translate"
          [desc]="'docs.notification.exDurationD' | translate">
          <sg-row [label]="'docs.notification.rowDuration' | translate">
            <hrm-button variant="default" (click)="durAuto()">{{ 'docs.notification.durAuto' | translate }}</hrm-button>
            <hrm-button variant="default" (click)="durStay()">{{ 'docs.notification.durStay' | translate }}</hrm-button>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.notification.exDedupT' | translate"
          [desc]="'docs.notification.exDedupD' | translate">
          <sg-row [label]="'docs.notification.rowDedup' | translate">
            <hrm-button variant="default" (click)="dedup()">{{ 'docs.notification.ddBtn' | translate }}</hrm-button>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.notification.exStackT' | translate"
          [desc]="'docs.notification.exStackD' | translate">
          <sg-row>
            <hrm-button variant="primary" (click)="stack()">{{ 'docs.notification.stBtn' | translate }}</hrm-button>
          </sg-row>
        </sg-example>
      </div>

    </sg-doc>
  `,
})
export class SgDocNotification {
  protected readonly notify = inject(HrmNotificationService);
  private readonly t = inject(TranslateService);

  protected readonly when = [
    'docs.notification.when1',
    'docs.notification.when2',
    'docs.notification.when3',
  ];

  protected ovInfo(): void { this.notify.info(this.t.instant('docs.notification.ovInfoTitle'), this.t.instant('docs.notification.ovInfoDesc')); }
  protected ovSuccess(): void { this.notify.success(this.t.instant('docs.notification.ovSuccessTitle'), this.t.instant('docs.notification.ovSuccessDesc')); }

  protected tInfo(): void { this.notify.info(this.t.instant('docs.notification.tInfoTitle'), this.t.instant('docs.notification.tInfoDesc')); }
  protected tSuccess(): void { this.notify.success(this.t.instant('docs.notification.tSuccessTitle'), this.t.instant('docs.notification.tSuccessDesc')); }
  protected tWarning(): void { this.notify.warning(this.t.instant('docs.notification.tWarningTitle'), this.t.instant('docs.notification.tWarningDesc')); }
  protected tError(): void { this.notify.error(this.t.instant('docs.notification.tErrorTitle'), this.t.instant('docs.notification.tErrorDesc')); }

  protected place(placement: 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight'): void {
    this.notify.info(
      this.t.instant('docs.notification.pl_' + placement + 'Title'),
      this.t.instant('docs.notification.pl_' + placement + 'Desc'),
      { placement },
    );
  }

  protected durAuto(): void {
    this.notify.success(this.t.instant('docs.notification.durAutoTitle'), this.t.instant('docs.notification.durAutoDesc'), { duration: 3000 });
  }

  protected durStay(): void {
    this.notify.error(this.t.instant('docs.notification.durStayTitle'), this.t.instant('docs.notification.durStayDesc'), { duration: 0 });
  }

  protected dedup(): void {
    this.notify.info(this.t.instant('docs.notification.ddTitle'), this.t.instant('docs.notification.ddDesc'), { key: 'sync-nv' });
  }

  protected stack(): void {
    this.notify.info(this.t.instant('docs.notification.stMsg1Title'), this.t.instant('docs.notification.stMsg1Desc'));
    this.notify.success(this.t.instant('docs.notification.stMsg2Title'), this.t.instant('docs.notification.stMsg2Desc'));
    this.notify.warning(this.t.instant('docs.notification.stMsg3Title'), this.t.instant('docs.notification.stMsg3Desc'));
  }
}
